# ---------------------------------------------------------------- references: number by first appearance
order = []
def repl(mt):
    keys = [k.strip().lstrip('@') for k in mt.group(1).split(';')]
    nums = []
    for k in keys:
        if k not in REFS:
            raise KeyError(k)
        if k not in order:
            order.append(k)
        nums.append(order.index(k) + 1)
    nums = sorted(set(nums)); out = []; i = 0
    while i < len(nums):
        j = i
        while j + 1 < len(nums) and nums[j + 1] == nums[j] + 1:
            j += 1
        out.append(f"{nums[i]}–{nums[j]}" if j - i >= 2 else (f"{nums[i]},{nums[j]}" if j == i + 1 else f"{nums[i]}"))
        i = j + 1
    return '[' + ','.join(out) + ']'
cite = re.compile(r'\[(@[^\]]+)\]')
newb = []
for b in blocks:
    if b[0] == 'table':
        hdr = [cite.sub(repl, h) for h in b[2]]
        rows = [[cite.sub(repl, str(c)) for c in r] for r in b[3]]
        newb.append(('table', cite.sub(repl, b[1]), hdr, rows, cite.sub(repl, b[4]) if b[4] else None))
    elif b[0] == 'fig':
        newb.append(('fig', b[1], cite.sub(repl, b[2]), b[3]))
    elif len(b) > 1 and isinstance(b[1], str):
        newb.append((b[0], cite.sub(repl, b[1])) + tuple(b[2:]))
    else:
        newb.append(b)
newb.append(('h1', 'References'))
for i, k in enumerate(order):
    newb.append(('ref', f"{i+1}.\t{REFS[k]}"))
unused = [k for k in REFS if k not in order]
docxwriter.write(newb, 'Manuscript_Revised.docx')
print('refs cited', len(order), 'unused', unused)
print('abstract words', len(abstract.split()))
